import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
import java.util.concurrent.TimeUnit;

public class ResourceController {
    private final Lock lock = new ReentrantLock(true); // Fair lock

    public void performCriticalTask() {
        try {
            // Try to acquire the lock within 3 seconds, making it interruptible
            if (lock.tryLock(3, TimeUnit.SECONDS)) {
                try {
                    // Critical section execution
                    System.out.println(Thread.currentThread().getName() + " acquired the lock.");
                } finally {
                    lock.unlock(); // Mandatory: always release in finally
                }
            } else {
                System.out.println(Thread.currentThread().getName() + " could not acquire lock.");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Thread interrupted while waiting for lock.");
        }
    }
}
